  onCategoryChecked(courseCategoryId: number | string) {

    if (this.courseCategoryIds.find(c => c == courseCategoryId) == null) {

      this.courseCategoryIds.push(+courseCategoryId);
    } else {
      this.courseCategoryIds.splice(this.courseCategoryIds.findIndex(c => c == courseCategoryId), 1);
    }
  }

  checkCategoryId(courseCategoryId: number | string): boolean {

    if (this.courseCategoryIds.find(c => c == courseCategoryId) == null) {

      return false;
    } else {

      return true;
    }
  }

  onUpdate() {

    if (this.updateCourseForm.valid) {

      if (this.courseCategoryIds.length < 1) {

        SharedIonic.toast(this.toastController, 'گروهی انتخاب نشده است');
        return;
      }

      if (+this.updateCourseForm.value.offPrice > +this.updateCourseForm.value.price) {

        SharedIonic.toast(this.toastController, 'تخفیف بیشتر از قیمت اصلی است');
        return;
      }

      SharedIonic.loading(this.loadingController);

      // this.shortDescription = this.domSanitizer
      //   .sanitize(SecurityContext.HTML, this.updateCourseForm.value.shortDescriptionHtmlContent);

      this.shortDescription = this.updateCourseForm.value.shortDescriptionHtmlContent;

      this.description = this.domSanitizer
        .sanitize(SecurityContext.HTML, this.updateCourseForm.value.descriptionHtmlContent);

      this.course =
        new AddOrUpdateCourseModel(
          this.selectedCourseId,
          this.updateCourseForm.value.name,
          this.updateCourseForm.value.price,
          this.updateCourseForm.value.offPrice,
          this.shortDescription,
          this.description,
          this.updateCourseForm.value.imageUrl,
          this.updateCourseForm.value.imageNamePNG,
          this.updateCourseForm.value.videoUrl,
          this.courseCategoryIds,
          this.updateCourseForm.value.isFinished,
          this.updateCourseForm.value.videoTime,
          this.updateCourseForm.value.size,
          this.updateCourseForm.value.level,
          this.updateCourseForm.value.hasDegree,
          this.updateCourseForm.value.freeExamCount,
          this.updateCourseForm.value.examPrice,
          this.updateCourseForm.value.examLevelCount,
          this.updateCourseForm.value.point,
          this.updateCourseForm.value.portionPercent,
          this.updateCourseForm.value.portionPrice,
          this.updateCourseForm.value.isStopped,
          this.updateCourseForm.value.stoppedReason,
          this.updateCourseForm.value.isBuy,
          this.updateCourseForm.value.isVip
        );

      this.courseService.AdminUpdateCourse(this.course).subscribe(
        res => {

          if (GResponse.SuccessStatus === res.status) {

            this.filteredCourses = new CourseFilterModel(true, 1, 12, '', null, null, [], 4);

            this.courseService.GetAdminCoursesByFilter(this.filteredCourses).subscribe(
              res2 => {
                SharedIonic.dismissLoading(this.loadingController);
                if (res2.status === GResponse.SuccessStatus) {
                  this.courseSelected = false;
                  this.filteredCourses = res2.data;
                  SharedIonic.successToast(this.toastController);
                } else {
                  SharedIonic.unSuccessToast(this.toastController);
                }
              },
              err => {
                SharedIonic.dismissLoading(this.loadingController);
                SharedIonic.unSuccessToast(this.toastController);
              }
            );
          } else {
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= +pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  goPreviousPage() {

    if (this.filteredCourses.startPage == null) {
      return;
    }
    if (this.filteredCourses.pageId > this.filteredCourses.startPage && +this.filteredCourses.pageId - 1 > 0) {
      this.setQueryParams(+this.filteredCourses.pageId - 1);
    }
  }

  goNextPage() {

    if (this.filteredCourses.endPage == null) {
      return;
    }
    if (this.filteredCourses.pageId < this.filteredCourses.endPage) {
      this.setQueryParams(+this.filteredCourses.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  setQueryParams(pageId: number) {

    this.filteredCourses.title = this.searchTitle;

    this.router
      .navigate(
        ['SuperAdminPanel', 'UpdateCourse'],
        {
          queryParams:
          {
            page: pageId < 1 ? 1 : pageId,
            take: this.filteredCourses.takeEntity ? this.filteredCourses.takeEntity : null,
            title: this.filteredCourses.title ? this.filteredCourses.title : null,
            startPrice: this.filteredCourses.startPrice ? this.filteredCourses.startPrice : null,
            endPrice: this.filteredCourses.endPrice ? this.filteredCourses.endPrice : null,
            categoryIds: this.filteredCourses.categoryIds ? this.filteredCourses.categoryIds : [],
            sortId: this.filteredCourses.sortId ? this.filteredCourses.sortId : 0
          }
        });
  }

